-- Platform legal documents: an operator/data processing agreement and a
-- safeguarding/operational disclaimer. The canonical editable copy lives in
-- document-service.js; these rows make the production catalogue deterministic.
-- ON CONFLICT DO NOTHING preserves any edits made by a platform administrator.
INSERT INTO documents (slug, title, category, role_key, lede, intro, sections, version)
VALUES
  ('safeguarding-disclaimer', 'Safeguarding & Operational Disclaimer', 'legal', NULL,
   'Where the centre’s duties end and the Re-EL ECD platform begins.',
   '["Re-EL ECD provides digital tools to support ECD administration and safeguarding procedures. It is software, not a childcare provider, regulator or certifying authority. This disclaimer forms part of the Terms of Service.", "This is general copy in plain language, not legal advice. Have a South African attorney review it for your facts before relying on it."]'::jsonb,
   '[{"heading":"The centre supervises the children","paragraphs":["The centre, its owner and its staff remain responsible for the physical supervision, care, safety and wellbeing of every child. Attendance registers, gate scans, collector records and alerts do not constitute supervision and never replace an attentive adult."],"steps":[]},{"heading":"The centre owns safeguarding policies and collection procedures","paragraphs":["Each centre must adopt, publish and review its own safeguarding policies, child-protection procedures and collection procedures under the Children’s Act 38 of 2005 and applicable DSD/DBE requirements."],"steps":[]},{"heading":"Authorised collectors must be registered correctly","paragraphs":["The centre must keep its authorised-collector list accurate. A successful gate scan is evidence of what the platform recorded, not proof that the right person collected the child, and never authorises a release on its own."],"steps":[]},{"heading":"Staff follow the centre’s verification procedures","paragraphs":["Staff must check identification and follow escalation steps every time. The platform can prompt and log those steps but cannot perform them."],"steps":[]},{"heading":"The platform does not replace people or the law","paragraphs":["Re-EL ECD does not replace physical supervision, vetted staff, professional judgement, mandatory reporting to the designated social worker, SAPS or the DSD, or any other regulatory requirement."],"steps":[]},{"heading":"No registration or compliance certification","paragraphs":["Using Re-EL ECD does not automatically register an ECD centre or certify legal compliance. Government ECD registration with the provincial DSD or DBE, and any other statutory approvals, are separate and remain the centre’s responsibility. Badges, registration-number fields and published website pages are user-supplied content, not proof of registration."],"steps":[]}]'::jsonb,
   1),
  ('data-processing-agreement', 'Operator / Data Processing Agreement', 'legal', NULL,
   'POPIA operator terms for personal information processed on behalf of a centre (DRAFT — attorney review required).',
   '["DRAFT FOR LEGAL REVIEW — NOT YET REVIEWED BY A SOUTH AFRICAN ATTORNEY. Do not sign or rely on this template until counsel has reviewed it and the parties have signed.", "This Operator / Data Processing Agreement sets out how Re-EL ECD Technologies (Pty) Ltd (operator) processes personal information on behalf of the subscribing ECD centre (responsible party) under the Protection of Personal Information Act 4 of 2013 (POPIA), especially sections 19 and 20.", "This is a template, not legal advice."]'::jsonb,
   '[{"heading":"1. Parties, roles and scope","paragraphs":["The centre determines why and how learner, guardian and staff information is used and is the responsible party. Re-EL ECD acts as operator and processes it only on the centre’s documented instructions."],"steps":[]},{"heading":"2. Lawful authority to collect children’s information","paragraphs":["The centre warrants that it has the permissions, lawful authority and POPIA basis to collect and disclose the information it enters, including guardian consent or another s35 basis for children, and compliance with the Children’s Act 38 of 2005."],"steps":[]},{"heading":"3. Re-EL ECD’s protection duties","paragraphs":["Re-EL ECD will process information lawfully, keep it confidential, maintain safeguards, bind personnel and sub-processors, assist with POPIA rights, and notify the centre of a compromise without unreasonable delay. It will not sell personal information or use it for third-party AI training."],"steps":[]},{"heading":"4. Permitted purposes","paragraphs":["Only to provide and support the Service, store centre records, deliver centre-initiated messages, maintain security, process payments, meet legal duties and follow further instructions."],"steps":[]},{"heading":"5. Hosting providers and third parties","paragraphs":["Sub-processors include Vercel, GitHub Pages, Neon PostgreSQL, Cloudflare R2, Resend, textbee / Africa’s Talking / Twilio, PayFast, browser push, Google Analytics 4, Google Search Console, Google Fonts and Open-Meteo. Cross-border transfers require POPIA s72 safeguards or another lawful basis."],"steps":[]},{"heading":"6. Access, sharing and disclosure restrictions","paragraphs":["Access is limited to authorised personnel under role-based permissions and tenant isolation. Support access is short-lived and audited. Disclosure is only on instruction, to listed sub-processors, where legally compelled, or to bound advisers."],"steps":[]},{"heading":"7. Security requirements","paragraphs":["TLS in transit, encryption at rest for secrets and provider-managed encryption, hashed passwords, optional MFA, short-lived sessions, CSRF protection, rate limits, audit logging and signed short-lived media URLs. Controls are reviewed at least annually."],"steps":[]},{"heading":"8. Termination of subscription","paragraphs":["Active access ends on expiry or termination. Data is kept securely for a short transition window for export, then deleted or anonymised subject to law."],"steps":[]},{"heading":"9. Export, retention and deletion","paragraphs":["Per-resource CSV, XLSX and PDF exports are available. Retention follows centre settings and law; residual copies are deleted or anonymised within 30 days after the transition window, except legal holds and backup cycles."],"steps":[]},{"heading":"10. Security incidents","paragraphs":["The centre must notify privacy@re-el.co.za without unreasonable delay. Re-EL ECD investigates, contains, remediates and, where serious harm is likely, notifies the Information Regulator and affected data subjects as POPIA s22 requires."],"steps":[]},{"heading":"11. General and signatures","paragraphs":["South African law governs. This Agreement forms part of the Terms and prevails for personal-information processing. Sign after attorney review."],"steps":[]}]'::jsonb,
   1)
ON CONFLICT (slug) DO NOTHING;

-- Additive legal notices to existing documents. These do not overwrite
-- platform-admin edits; they only add a clause if it is not already present.
UPDATE documents
SET sections = sections || '[{"heading":"Registration and legal compliance","paragraphs":["Using Re-EL ECD does not automatically register an ECD centre or certify that it is legally compliant. South African government ECD registration with the relevant provincial DSD or DBE, and any other statutory approvals, are separate processes that remain the centre’s responsibility. Platform badges, registration-number fields and published website content are user-supplied and are not proof of registration. See the Safeguarding & Operational Disclaimer."],"steps":[]}]'::jsonb,
    version = version + 1,
    updated_at = now()
WHERE slug = 'terms'
  AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(sections) AS s
    WHERE s->>'heading' ILIKE '%registration%'
  );

UPDATE documents
SET intro = intro || '["The Operator / Data Processing Agreement sets out the terms on which Re-EL ECD processes personal information on behalf of the centre."]'::jsonb,
    version = version + 1,
    updated_at = now()
WHERE slug = 'privacy'
  AND NOT (intro::text ILIKE '%Data Processing Agreement%');
